select throws_ok($$select save_native_prescription_draft(gen_random_uuid(),(select jsonb_set(v||jsonb_build_object('draft_id',gen_random_uuid()),'{fields,medication,name}',to_jsonb(E'\tSynthetic'::text)) from data where k='save-request'))$$,'23514','Invalid prescription text','Boundary whitespace rejected');
