select throws_ok($$select save_native_prescription_draft(gen_random_uuid(),(select jsonb_set(v||jsonb_build_object('draft_id',gen_random_uuid()),'{fields,fulfillment_mode}','"external_pharmacy"') from data where k='save-request'))$$,'23514','External orders cannot select stock','External order cannot retain local product');
select throws_ok($$select save_native_prescription_draft(gen_random_uuid(),(select jsonb_set(v||jsonb_build_object('draft_id',gen_random_uuid()),'{fields,refills_authorized}','1001') from data where k='save-request'))$$,'23514','Invalid refill allowance','Refill bound enforced');
select throws_ok($$select save_native_prescription_draft(gen_random_uuid(),(select jsonb_set(v||jsonb_build_object('draft_id',gen_random_uuid()),'{fields,expires_on}','"2026-02-30"') from data where k='save-request'))$$,'23514','Invalid prescription date','Invalid calendar date rejected');
select set_config('request.jwt.claims','{"sub":"a5510000-0000-4000-8000-000000000004","role":"authenticated"}',true);
