select is((select jsonb_array_length(list_native_prescription_drafts((select id from fx where k='pet'),(v#>>'{next_cursor,before_at}')::timestamptz,(v#>>'{next_cursor,before_id}')::uuid,1)->'drafts') from data where k='page'),1,'Draft cursor retains earlier record');
select configure_native_prescriber(gen_random_uuid(),(select jsonb_set(v||'{"expected_version":1}','{fields,active}','false') from data where k='config-request'));
