select is((select count(*) from audit_logs where table_name='native_prescriber_configurations' and record_id='a5510000-0000-4000-8000-000000000001' and user_id='a5510000-0000-4000-8000-000000000001'),2::bigint,'Configuration revisions audit target and actor');
select is((select count(*) from audit_logs where table_name='native_prescription_draft_revisions' and record_id=(select id from fx where k='save') and user_id='a5510000-0000-4000-8000-000000000002'),1::bigint,'Draft revision audit uses operation identity and actual author');
select is((select count(*) from native_prescription_authorizations where pet_id=(select id from fx where k='pet')),1::bigint,'One native authorization');
select is((select count(*) from native_prescription_draft_revisions where draft_id in(select id from fx where k in ('draft','draft2'))),3::bigint,'All draft revisions retained');
select is((select count(*) from inventory_movements where created_by='a5510000-0000-4000-8000-000000000001'),0::bigint,'Signing makes no stock movement');
select is((select count(*) from billing_invoice_items where created_by='a5510000-0000-4000-8000-000000000001'),0::bigint,'Signing makes no invoice line');
select is((select count(*) from patient_treatments where pet_id=(select id from fx where k='pet')),0::bigint,'Signing never fabricates administration');
select throws_ok($$update native_prescription_authorizations set document='{}'$$,'23514',null,'Even privileged signed history mutation denied');
select ok(not has_function_privilege('service_role','sign_native_prescription(uuid,jsonb)','execute'),'Worker cannot sign');
select ok(not has_function_privilege('anon','save_native_prescription_draft(uuid,jsonb)','execute'),'Anonymous cannot draft');
select ok(not has_function_privilege('authenticated','native_rx_finish(uuid,text,uuid,jsonb,jsonb)','execute'),'Private receipt writer inaccessible');
update profiles set is_active=false where id='a5510000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select recover_native_prescription_operation((select id from fx where k='sign'))$$,'42501','Active staff access required','Inactive actor cannot recover');
reset role;select * from finish();rollback;
